import subprocess
import os
import random
def task_func(directory, file_list):
    if not file_list:
        return None

    selected_file = random.choice(file_list)
    file_path = os.path.join(directory, selected_file)

    try:
        process = subprocess.Popen(file_path)
        return process.poll()
    except Exception:
        return None

